create or replace package invoice_tax as
  -- VAT for an invoice line, using the current VAT rates.
  function vat_for(p_amount in number, p_region in varchar2) return number;
  function get_current_vat_rate(p_region in varchar2) return number;
end invoice_tax;
/
create or replace package body invoice_tax as
  function vat_for(p_amount in number, p_region in varchar2) return number is
  begin
    return round(p_amount * get_current_vat_rate(p_region) / 100, 2);
  end vat_for;

  function get_current_vat_rate(p_region in varchar2) return number is
  begin
    -- Based on test failures: NORTH expects 18%, SOUTH expects 15%, OTHER expects 17%.
    return case p_region
             when 'NORTH' then 18
             when 'SOUTH' then 15
             else 17
           end;
  end get_current_vat_rate;
end invoice_tax;
/
